**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <iomanip>
using namespace std;

struct Uczen {
    string imie;
    int wiek;
    double srednia;
};

int main() {
    ifstream plik("uczniowie.txt");
    int N;
    plik >> N;
    vector<Uczen> tab(N);
    for (int i = 0; i < N; i++)
        plik >> tab[i].imie >> tab[i].wiek >> tab[i].srednia;

    // a) Max srednia globalna
    int idxMax = 0;
    for (int i = 1; i < N; i++)
        if (tab[i].srednia > tab[idxMax].srednia) idxMax = i;

    // b) Min srednia wsrod wiek >= 17
    int idxMinW = -1;
    for (int i = 0; i < N; i++) {
        if (tab[i].wiek >= 17) {
            if (idxMinW == -1 || tab[i].srednia < tab[idxMinW].srednia)
                idxMinW = i;
        }
    }

    // c) Rozstep srednich
    double minSr = tab[0].srednia, maxSr = tab[0].srednia;
    for (int i = 1; i < N; i++) {
        if (tab[i].srednia < minSr) minSr = tab[i].srednia;
        if (tab[i].srednia > maxSr) maxSr = tab[i].srednia;
    }

    cout << fixed << setprecision(2);
    cout << "a) Najwyzsza srednia: " << tab[idxMax].imie
         << " (" << tab[idxMax].srednia << ")" << endl;
    if (idxMinW != -1)
        cout << "b) Najnizsza srednia (wiek >= 17): " << tab[idxMinW].imie
             << " (" << tab[idxMinW].srednia << ")" << endl;
    else
        cout << "b) Brak uczniow w wieku >= 17" << endl;
    cout << "c) Rozstep srednich: " << maxSr - minSr << endl;
    return 0;
}
```

**Wyjasnienie**: Trzy osobne przebiegi po wektorze struktur. (a) Globalny max sredniej — proste szukanie. (b) Warunkowe min z filtrem na wiek — flaga idxMinW=-1 sluzy jako "jeszcze nie znaleziono". (c) Min i max srednia globalnie, rozstep = max - min.

Weryfikacja:
- Srednie: 4.75, 3.20, 5.00, 4.50, 3.80, 4.10, 4.90, 2.95
- (a) Max srednia: 5.00 (Celina)
- (b) Wiek >= 17: Bartek(3.20), Celina(5.00), Ewa(3.80), Filip(4.10), Hubert(2.95) -> min = 2.95 (Hubert)
- (c) Min srednia = 2.95, max = 5.00, rozstep = 2.05.
